const $ = (s) => document.querySelector(s);
const wa = (text) => `https://wa.me/5588997101831?text=${encodeURIComponent(text)}`;
const modes={
 ai:{label:'EXPERIMENTO_01 / IA',title:'Sua equipe tem<br>mais o que criar.',description:'Organizar informações, estruturar respostas, conectar processos. A IA pode assumir parte do repetitivo e abrir espaço para o que precisa de você.',cta:'Quero explorar IA no meu negócio',name:'inteligência artificial'},
 wa:{label:'EXPERIMENTO_02 / WHATSAPP',title:'Cada conversa<br>tem um caminho.',description:'Um primeiro contato organizado faz diferença. Experimente uma jornada com perguntas claras, opções úteis e o próximo passo na hora certa.',cta:'Quero conectar meu atendimento',name:'automação de WhatsApp'},
 content:{label:'EXPERIMENTO_03 / CONTEÚDO',title:'A mesma ideia.<br>Outra intenção.',description:'Uma marca tem muitas histórias para contar. Veja como um tema pode ganhar direções diferentes, mantendo uma mensagem clara e uma voz própria.',cta:'Quero dar voz à minha marca',name:'criação de conteúdo'},
 web:{label:'EXPERIMENTO_04 / SITES',title:'Sua presença.<br>Do seu jeito.',description:'Seu site pode ter personalidade e continuar simples de usar. Mude a direção visual desta pequena experiência e imagine a identidade do seu negócio.',cta:'Quero um site com personalidade',name:'criação de sites'}
};
let mode='ai',timer=null;
function frame(title,body){return `<div class="demo-bar"><span>${title}</span><span>DEMO / INTERATIVA</span></div><div class="demo-body">${body}</div>`}
function activate(next,scroll=false){if(!modes[next])return;clearTimeout(timer);mode=next;const m=modes[mode];document.querySelectorAll('[data-mode]').forEach(b=>{const active=b.dataset.mode===mode;if(b.getAttribute('role')==='tab'){b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1}else b.classList.toggle('selected',active)});$('#demo-label').textContent=m.label;$('#demo-title').innerHTML=m.title;$('#demo-description').textContent=m.description;$('#demo-contact').firstChild.textContent=m.cta+' ';$('#demo-contact').href=wa(`Olá! Quero conversar sobre ${m.name} para meu negócio.`);$('#demo').setAttribute('aria-labelledby',`tab-${mode}`);render();if(scroll)$('#laboratorio').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function render(){
 if(mode==='ai'){$('#demo').innerHTML=frame('FLUXO_01 / ORGANIZAR UM PEDIDO',`<span class="demo-label">ENTRADA / MENSAGEM RECEBIDA</span><div class="demo-task">“Preciso de um site para minha loja.<br>Quero mostrar os produtos e receber contatos.” <span>↗</span></div><button class="demo-action" id="run-ai">Simular organização do pedido <span>→</span></button><div class="output" id="ai-output" aria-live="polite"><span class="hint">CLIQUE PARA VER A INFORMAÇÃO GANHAR ESTRUTURA.</span></div><p class="hint">Exemplo pré-definido. Não utiliza um modelo de IA real.</p>`);$('#run-ai').onclick=()=>{const b=$('#run-ai');b.disabled=true;$('#ai-output').innerHTML='<span class="step">01 / Lendo a intenção do pedido…</span>';timer=setTimeout(()=>{if(mode!=='ai')return;$('#ai-output').innerHTML='<span class="step">✓ Pedido estruturado</span><ul><li>Objetivo: apresentar produtos</li><li>Canal: site da loja</li><li>Ação principal: receber contatos</li><li>Próximo passo: definir catálogo e páginas</li></ul>';b.textContent='Simular novamente ↻';b.disabled=false},850)}}
 if(mode==='wa'){$('#demo').innerHTML=frame('JORNADA_02 / PRIMEIRO CONTATO',`<div class="chat-flow" id="chat" aria-live="polite"><div class="message">Olá! Esta é a experiência de demonstração da Supera. Por onde você quer começar?</div><div class="chat-choices"><button data-chat="site">Quero um site</button><button data-chat="automation">Quero automatizar</button></div></div><p class="hint">Fluxo ilustrativo. Nenhuma mensagem é enviada.</p>`);bindChat()}
 if(mode==='content'){$('#demo').innerHTML=frame('ESTÚDIO_03 / UMA IDEIA, TRÊS VOZES',`<span class="demo-label">TEMA / SEU NEGÓCIO NO DIGITAL</span><div class="content-controls"><select id="tone" aria-label="Direção do conteúdo"><option value="direct">Direto ao ponto</option><option value="creative">Criativo</option><option value="close">Próximo e humano</option></select><button class="demo-action" id="change-tone">Aplicar ↗</button></div><div class="content-result" id="content-result" aria-live="polite"></div><p class="hint">Exemplos editoriais pré-escritos para explorar tons de voz.</p>`);const content={direct:['Sua marca merece ser encontrada.','Um site claro conecta o que sua empresa faz a quem precisa dela. Vamos construir esse caminho?'],creative:['Sua melhor vitrine não fecha às 18h.','Ideias boas merecem um endereço no digital. Abra espaço para sua marca aparecer, conectar e surpreender.'],close:['Vamos apresentar seu negócio ao mundo?','Você cuida de cada detalhe da sua empresa. A gente ajuda a contar essa história em um site que tem a sua cara.']};const update=()=>{const c=content[$('#tone').value];$('#content-result').innerHTML=`<span>ESTUDO DE TEXTO / ${$('#tone').selectedOptions[0].text.toUpperCase()}</span><h4>${c[0]}</h4><p>${c[1]}</p>`};$('#change-tone').onclick=update;update()}
 if(mode==='web'){$('#demo').innerHTML=frame('CANVAS_04 / MUDE A DIREÇÃO',`<div class="web-controls">PALETA / <button class="swatch" style="background:#3464f4" data-palette="blue" aria-label="Usar paleta azul" aria-pressed="true"></button><button class="swatch" style="background:#b65734" data-palette="clay" aria-label="Usar paleta terracota" aria-pressed="false"></button><button class="swatch" style="background:#3e6b50" data-palette="green" aria-label="Usar paleta verde" aria-pressed="false"></button></div><div class="mini-browser"><div class="browser-dots">•••</div><div class="mini-site"><small>SEU NEGÓCIO / NOVAS POSSIBILIDADES</small><h4>Uma boa ideia.<br>Um novo lugar<br>para acontecer.</h4><p>Uma pequena amostra de direção visual.</p><span>Vamos conversar ↗</span></div></div><p class="hint">Protótipo visual ilustrativo. Escolha uma cor acima.</p>`);document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{const p={blue:['#e4eafd','#3464f4'],clay:['#eee0d7','#b65734'],green:['#dee8d9','#3e6b50']}[b.dataset.palette];$('.mini-browser').style.background=p[0];$('.mini-site>span').style.background=p[1];document.querySelectorAll('[data-palette]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))})}
}
function bindChat(){document.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>{const chat=$('#chat');const website=b.dataset.chat==='site';chat.innerHTML=`<div class="message visitor">${b.textContent}</div><div class="message">${website?'Ótimo! O foco é apresentar sua empresa ou uma oferta específica?':'Vamos entender sua rotina. Você quer organizar dúvidas frequentes ou o primeiro contato?'}</div><div class="chat-choices"><button data-next="a">${website?'Apresentar minha empresa':'Dúvidas frequentes'}</button><button data-next="b">${website?'Divulgar uma oferta':'Primeiro contato'}</button></div>`;document.querySelectorAll('[data-next]').forEach(n=>n.onclick=()=>{const answer=n.textContent;chat.innerHTML=`<div class="message visitor">${answer}</div><div class="message">Caminho identificado. Agora uma pessoa pode entender os detalhes e preparar uma proposta com você.</div><a class="demo-action" href="${wa(`Olá! Explorei a demonstração e quero ${website?'um site':'uma automação de WhatsApp'}. Meu foco: ${answer.toLowerCase()}.`)}" target="_blank" rel="noopener noreferrer">Continuar com a Supera de verdade ↗</a><button class="mini-reset" id="reset-chat">Recomeçar demonstração ↻</button>`;$('#reset-chat').onclick=render})})}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>activate(b.dataset.mode,b.classList.contains('node')));
document.querySelectorAll('[role=tab]').forEach((b,i)=>b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')];const n=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;activate(tabs[n].dataset.mode);tabs[n].focus()}));
$('.menu').onclick=()=>{const open=$('.header nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open));$('.menu').setAttribute('aria-label',open?'Fechar navegação':'Abrir navegação');$('.menu').textContent=open?'×':'☰'};
document.querySelectorAll('.header nav a').forEach(a=>a.onclick=()=>{$('.header nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');$('.menu').textContent='☰';$('.menu').setAttribute('aria-label','Abrir navegação')});
$('#contact-form').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name){$('#name').focus();return}window.open(wa(`Olá! Meu nome é ${name}. Tenho interesse em: ${$('#interest').value.toLowerCase()}. Podemos conversar?`),'_blank','noopener,noreferrer')};
$('#year').textContent=new Date().getFullYear();
$('#motion').onclick=()=>{const paused=document.body.classList.toggle('paused');$('#motion').setAttribute('aria-pressed',String(paused));$('#motion').textContent=paused?'Retomar movimento ▷':'Pausar movimento Ⅱ'};
const sculpture=$('.sculpture'), inner=$('.sculpture-inner');let dragging=false,startX=0,rotation=0;
function rotate(value){rotation=((value%360)+360)%360;inner.style.animation='none';inner.style.transform=`rotateX(12deg) rotateY(${rotation}deg) rotateZ(-12deg)`;sculpture.setAttribute('aria-valuenow',String(Math.round(rotation)))}
sculpture.addEventListener('pointerdown',e=>{dragging=true;startX=e.clientX-rotation;sculpture.setPointerCapture(e.pointerId)});sculpture.addEventListener('pointermove',e=>{if(dragging)rotate(e.clientX-startX)});['pointerup','pointercancel'].forEach(type=>sculpture.addEventListener(type,()=>dragging=false));sculpture.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();rotate(rotation+(e.key==='ArrowRight'?15:-15))}});
activate('ai');
